import Image from 'next/image';
import { cn } from '@/lib/utils';

// Intrinsic aspect ratios of the files in public/brand (generated by
// scripts/brand-assets/build_logo.py). Light and dark artwork swap with the theme class.
const ART = {
    lockup: { light: '/brand/auravine-logo.svg', dark: '/brand/auravine-logo-dark.svg', ratio: 1055.33 / 168.84 },
    mark: { light: '/brand/auravine-mark.svg', dark: '/brand/auravine-mark-dark.svg', ratio: 197.32 / 168.84 },
} as const;

type LogoProps = {
    /** `lockup` = mark + wordmark, `mark` = symbol only. */
    variant?: keyof typeof ART;
    /** Rendered height in px. */
    height?: number;
    className?: string;
    priority?: boolean;
};

export function Logo({ variant = 'lockup', height = 28, className, priority }: LogoProps) {
    const art = ART[variant];
    const width = Math.round(height * art.ratio);
    const common = { width, height, alt: '', unoptimized: true, priority, draggable: false } as const;
    return (
        <span className={cn('inline-flex shrink-0 items-center', className)} style={{ height }}>
            <Image src={art.light} {...common} className="block dark:hidden" />
            <Image src={art.dark} {...common} className="hidden dark:block" />
        </span>
    );
}
